workingMemoryInput:
// Assert runtime facts here, one per line.
// The case under adjudication: Samuelson & Marks, Managerial Economics Ch.13 Fig 13.3
Program( id: "RND-13.3", domain: "INCREMENTAL_RND", stagesAttempted: 0, maxStages: 5 )

// Probe A — escalation of commitment. Uncomment BOTH lines:
// Program( id: "RND-13.3", domain: "INCREMENTAL_RND", stagesAttempted: 3, maxStages: 5 )
// SunkCost( programId: "RND-13.3", amountSpent: 9000 )

// Probe B — breakthrough risk override. Replace the HazardProfile fact with:
// HazardProfile( programId: "RND-13.3", direction: "INCREASING", terminalHitRate: 0.95, successAttainable: false )
// and set domain: "BREAKTHROUGH_RND".

factSets.facts:
// STATED. Units: $000s. Stationarity flags carry the 'and no other
// facts change' precondition of the Monotone Continuation Theorem.
StageEconomics( programId: "RND-13.3", incrementalCost: 3000, successPayoff: 10000, costIsStationary: true, payoffIsStationary: true )

// Empty at session start (stagesAttempted = 0).
// Mid-program probe — uncomment to exercise the exclusion guard:
// SunkCost( programId: "RND-13.3", amountSpent: 9000 )

// basis vocabulary: MEASURED | THIRD_PARTY | INFERRED | INTROSPECTIVE
// INTROSPECTIVE is inadmissible as grounding for any rate (see rs-evidence).
// Empty at session start. Assert one Evidence fact per grounded field.
// Example:
// Evidence( programId: "X", subject: "hazardDirection", basis: "MEASURED", instrument: "third-party assessment", observations: 4 )

// assetClass vocabulary: TIME_SAVED | SALARY_UPLIFT | OPTION_VALUE | NON_INSTRUMENTAL
// substitutionRatio: fraction of the payoff an EXISTING workaround already captures.
// quantified == false blocks all EV derivation and is reported, never estimated.
// Empty at session start.

// Uncomment the block below to re-adjudicate under rev 3.
// Program( id: "JPN-LISTENING", domain: "INCREMENTAL_RND", stagesAttempted: 14, maxStages: 20 )
// HazardProfile( programId: "JPN-LISTENING", direction: "INCREASING", terminalHitRate: 0.60, successAttainable: true )
// SunkCost( programId: "JPN-LISTENING", amountSpent: 5500 )
// Evidence( programId: "JPN-LISTENING", subject: "hazardDirection", basis: "INTROSPECTIVE", instrument: "self-report", observations: 0 )
// PayoffAsset( programId: "JPN-LISTENING", assetClass: "SALARY_UPLIFT", isSubstituted: true, substitutionRatio: 0.87, quantified: false )
//
// WITHHELD, NOT MISSING BY OVERSIGHT:
//   StageEconomics — successPayoff unquantified; asserting an int here would be invention.
//   Stage x20      — conditionalHitRate series unknown; no value may be estimated.
//   CandidatePolicy — no EV derivable without payoff or hazard series.

rules.then:
insert( new Decision( $pid, "ADOPT_INTERIOR_OPTIMUM", "Success is not guaranteed by exhaustion (terminal rate " + $t + "), so corner collapse is unavailable and the Monotone Continuation Theorem does not apply. Highest-EV policy is " + $lbl + ", stopping after " + $k + " failures", $best.doubleValue() ) );
insert( new InteriorOptimum( $pid, $lbl, $k, $best.doubleValue(), "Selected by argmax over the enumerated policy space — NOT by the theorem. An interior stopping rule is legitimate here and is not evidence of irresolution" ) );
setFocus( "AUDIT" );

insert( new Decision( $pid, "HALT_INSUFFICIENT_FACTS", "Corner collapse unavailable and the policy space is empty — there is nothing to rank. The decision is BLOCKED BY ABSENT FACTS, which is not the same finding as an adverse decision and must never be reported as one", 0.0 ) );
insert( new Defect( $pid, "POLICY_SPACE_EMPTY", "strategy-space", "Supply the per-stage hazard series and a quantified payoff, then re-run. Absence of a verdict is not a verdict" ) );
setFocus( "AUDIT" );
